// Define a function that walks one square
function walkSquare(size) {
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < size; j++) {
      moveForward();
    }
    turnRight();
  }
}

// Call it!
walkSquare(2);
// Now move to the goal
moveForward();
moveForward();
moveForward();
moveForward();
moveForward();
